    var limit = Math.max(0, taxable - Math.max(0, prior - nz(o.priorDed)));             /* 공제 종합한도: 과세가액 − 사전증여재산 과세표준 */
    var ded = Math.min(dedSum, limit);
    var base = Math.max(0, taxable - ded);
