  function pdTxt(r) { return r.pd ? md(r.pd) + ' 종가' : '현재가'; }
  function capTxt(r) {
    if (r.mk === 'kr') { var j = r.m / 1e12; return (j >= 100 ? comma(Math.round(j)) : comma(j, 1)) + '조원'; }
    return r.m >= 1e12 ? comma(r.m / 1e12, 2) + '조 달러' : comma(Math.round(r.m / 1e8)) + '억 달러';
  }
