    if (key === 'debt') return v <= 100 ? 'er-good' : v <= 200 ? '' : 'er-warn';
    if (key === 'icr') return v >= 5 ? 'er-good' : v >= 1.5 ? '' : v >= 1 ? 'er-warn' : 'er-bad';
