          y: { grid: { color: grid }, border: { display: false }, title: { display: true, text: '근로자 수', color: tick, font: { size: 11 } },
               ticks: { color: tick, font: { size: 10 }, callback: function (v) { return v ? Math.round(v / 1e4).toLocaleString('ko-KR') + '만' : '0'; } } }
