    var one = vCompute(X.s, X.before.concat([tx]), X.ses.midEntry), C = X.C, cur = X.s.currency || 'USD', sellQ = 0;
    tx.fills.forEach(function (f) { if (f.side === 'S') sellQ += f.q; });
    var over = sellQ > C.totalQuantity + 1e-9;
