    var nx = rb ? '새 사이클 (같은 날 다시 매수)' : MODE_NOTE[one.mode] && one.totalQuantity > 0 ? MODE_NOTE[one.mode][0] : phName(one.phase);
    var el = $('mh-vr-prev');
