    var h = '<div class="mh-bt-sel">' + chips + '</div><div class="mh-bt-sel mh-bt-sel2">' + (P.btPre ? b('bt-pre', null, BT.pre, (BT.pre ? '✓ ' : '＋ ') + '상장 전 포함', ' mh-bt-pre') : '') + vw + '</div>';
