        var cfg = Rr.cfg, o = { from: 1, capital: cap, norm: 'auto', rows: false, rej: Rr.rej || null, fill: Rr.fill || null };
        var a = V.run(cfg, D0, o), b = V.run(cfg, late, o), yrs = (B.dnum(D0.d[D0.d.length - 1]) - B.dnum(D0.d[0])) / 365.25;
