    if (X.rs > 0) W.push('사이클 안에서 가격이 크게 떨어져 가격 단위를 ' + X.rs + '번 바꿔 계산했어요 (실제 ETF 의 액면 병합처럼 보유 수량은 10분의 1로, 평단은 10배로 — 손익은 같음).');
