  window.addEventListener('dc-auth', function () { if (!loggedIn()) set(false); else if (cached()) set(true); });   /* 로그아웃하면 바로 닫음 */
  if (cached() || TEST) st = true;              /* 지난번 확인 결과로 먼저 열고, [AUTH] 가 서버 확인 뒤 set() 으로 바로잡음 */
  else if (!loggedIn()) st = false;
  apply();
