  function rng(a, b, s) { var o = []; for (var v = a; v <= b + 1e-9; v += s) o.push(+v.toFixed(4)); return o; }
  function opts(vals, lab) { return vals.map(function (v) { return [String(v), lab ? lab(v) : String(v)]; }); }
