  var DAYS = opts(rng(0, 15, 1).concat([20, 25, 30, 42, 63, 84, 105, 126]), function (v) { return v === 0 ? '즉시' : v === 42 ? '2개월' : v === 63 ? '3개월' : v === 84 ? '4개월' : v === 105 ? '5개월' : v === 126 ? '6개월' : v + '일'; });
  var WIN = opts(rng(10, 300, 10));
