    coolw: opts(rng(2, 30, 1)), cool: opts(rng(10, 90, 5), function (v) { return v + ' 미만'; }).concat([['0', '수준 상관없이 (끔)']]),
    out: ['cash', 'qqq', 'spy', 'tqqq', 'qld', 'sso', 'spxl', 'sqqq'].map(function (v) { return [v, tk(v)]; }),
