    din: DAYS, dout: DAYS,
    cost: opts([0, 0.01, 0.02, 0.03, 0.05, 0.1, 0.15, 0.2, 0.25, 0.3, 0.5, 0.75, 1], function (v) { return v + '%'; }),
    bga: ['qqq', 'spy', 'tqqq', 'qld', 'sso', 'spxl', 'sqqq'].map(function (v) { return [v, tk(v)]; }),
