    sum('etc', r.penalty + r.addBack + r.prepaid ? '기납부 ' + eok(r.prepaid) + (r.penalty + r.addBack ? ' · 가산 ' + eok(r.penalty + r.addBack) : '') : '');
    /* 결과 */
